/**
 * Pure helpers for the ASM admin-registration calls made by adminslist
 * (`addServiceProviderAdmin.ap`, `tenantAdmin.ap`). Implementation plan W18:
 * the W9 log/response rules applied to these two calls.
 *
 *  - Nothing from an ASM body is logged verbatim: `safeAsmDetail` (shared
 *    with provision-tenant) gives field names, known code fields and the
 *    free-text fields with every request value we sent redacted.
 *  - `Error.message` is our own text (the UI shows it as-is), never ASM's.
 *  - A stable `code` lets callers and the UI branch without string-matching.
 *
 * Kept free of SDK / layer imports so it can be unit-tested.
 */
import { safeAsmDetail } from "../provision-tenant/asm-register-request.mjs";

/** ASM's text for an admin that is already registered (AsmPortal_API_Documentation §14). */
const ADMIN_EXISTS_RE = /already exists/i;

/**
 * Stable codes -> HTTP status we return and the text the UI shows.
 * 409 is the one case the operator can act on (pick another email or
 * remove the existing admin); everything else is upstream, so 502.
 */
export const ASM_ADMIN_ERRORS = Object.freeze({
  asm_admin_exists: {
    statusCode: 409,
    userMessage: "This email is already registered as an admin on the ASM portal.",
  },
  asm_forbidden: {
    statusCode: 502,
    userMessage: "The ASM portal rejected this installation's credentials; the admin was not registered.",
  },
  asm_invite_email_failed: {
    statusCode: 502,
    userMessage: "The ASM portal could not send the admin invitation email; the admin was not registered.",
  },
  asm_error: {
    statusCode: 502,
    userMessage: "The ASM portal returned an error; the admin was not registered.",
  },
});

/**
 * Build the Error for a failed ASM admin call. `asmError: true` is what
 * adminslist/index.mjs branches on; `detail` is server-log only.
 */
export function asmAdminError(code, operation, httpStatus, body, secrets) {
  const entry = ASM_ADMIN_ERRORS[code] || ASM_ADMIN_ERRORS.asm_error;
  const err = new Error(entry.userMessage);
  err.code = ASM_ADMIN_ERRORS[code] ? code : "asm_error";
  err.asmError = true;
  err.statusCode = entry.statusCode;
  err.asmOperation = operation;
  err.asmStatus = httpStatus;
  err.detail = safeAsmDetail(body, { secrets });
  return err;
}

/**
 * Interpret an ASM admin-call reply. Returns the parsed body on success,
 * throws a classified Error otherwise.
 *
 * Failure triggers are the ones adminslist always used: a non-2xx HTTP
 * status, a non-JSON body, or a 2xx body whose `code` / `statusCode` is
 * >= 400, whose `status` is "Failed", or whose per-admin email status code
 * (`adminStatusCode` for SPA, `newTenantAdminEmailStatusCode` for TA) is 400.
 *
 * @param {number} httpStatus  fetch response status
 * @param {string} text        raw body
 * @param {{operation: "addServiceProviderAdmin"|"tenantAdmin", secrets?: string[]}} opts
 *        `secrets`: the request values ASM may echo (install key / org
 *        secret, emails); redacted from the logged detail.
 */
export function parseAsmAdminResponse(httpStatus, text, { operation, secrets = [] }) {
  const body = String(text || "");
  if (httpStatus < 200 || httpStatus >= 300) {
    throw asmAdminError(classify(httpStatus, body), operation, httpStatus, body, secrets);
  }
  let result;
  try {
    result = JSON.parse(body);
  } catch {
    throw asmAdminError("asm_error", operation, httpStatus, body, secrets);
  }
  if (!result || typeof result !== "object") {
    throw asmAdminError("asm_error", operation, httpStatus, body, secrets);
  }
  const bodyCode = Number.isInteger(result.code) ? result.code : Number.isInteger(result.statusCode) ? result.statusCode : null;
  const emailCode = operation === "tenantAdmin" ? result.newTenantAdminEmailStatusCode : result.adminStatusCode;
  const failed = (bodyCode !== null && bodyCode >= 400) || emailCode === 400 || result.status === "Failed";
  if (failed) {
    // Only the per-admin email code failed: the admin exists but the invite did not go out.
    const inviteOnly = emailCode === 400 && !(bodyCode !== null && bodyCode >= 400) && result.status !== "Failed";
    throw asmAdminError(inviteOnly ? "asm_invite_email_failed" : classify(bodyCode, body), operation, httpStatus, body, secrets);
  }
  return result;
}

/** Map a status (HTTP or body `code`) plus the body to a stable code. Called only for failures; text is matched, never copied. */
function classify(status, body) {
  if (status === 403) return "asm_forbidden";
  if (ADMIN_EXISTS_RE.test(body)) return "asm_admin_exists";
  return "asm_error";
}
