/**
 * Pure helpers for the ASM `newTenantAssignmentWithDefaults.ap` call
 * (design doc 1.6, 3.1 items 8-9; implementation plan W9). Kept free of
 * the `admin-auth` layer import so they can be unit-tested.
 */

/** ASM's text for a license key that is already bound to another client (question 28). */
const KEY_USED_RE = /license key is already used/i;

/**
 * What of an ASM reply may be logged. ASM may echo request values (license
 * key, secret, emails) anywhere in its reply, including free-text fields
 * such as `message` or `detail`, so NO string value from the body is ever
 * logged. For a JSON body: the field names present (at most
 * MAX_FIELDS, each cut to MAX_FIELD_NAME chars, since a hostile body can
 * put anything in a key), the numeric values of the KNOWN code fields
 * (CODE_FIELDS; not "anything ending in StatusCode", which is unbounded),
 * and the UTF-8 byte length. For anything else: the byte length plus the
 * one phrase we branch on (matched, not copied). Output is bounded.
 *
 * Opt-in `secrets` (an array of the request values we sent: license key,
 * org secret, emails): the caller vouches that these are the only secrets
 * the reply can echo, and in return the known free-text fields `message`
 * and `status` (or the text body) are included with every occurrence of
 * each secret, raw or URL-encoded, case-insensitively replaced by
 * "(redacted)" and the result cut to MAX_TEXT chars. Without `secrets`
 * nothing from the body is copied. Either way the output is server-log
 * only; `Error.message` and callers never get it (W9 rule).
 */
const MAX_FIELDS = 20;
const MAX_FIELD_NAME = 40;
const MAX_TEXT = 300;
const CODE_FIELDS = ["code", "newTenantAdminEmailStatusCode", "asmTenantInstallerEmailStatusCode"];
const TEXT_FIELDS = ["message", "status"];
export function safeAsmDetail(text, { secrets } = {}) {
  const body = String(text || "");
  const bytes = Buffer.byteLength(body, "utf8");
  const used = KEY_USED_RE.test(body) ? ", license key already used" : "";
  const withText = Array.isArray(secrets);
  let parsed;
  try {
    parsed = JSON.parse(body);
  } catch {
    return `(text body, ${bytes} bytes${used})` + (withText ? ` ${JSON.stringify(redact(body, secrets))}` : "");
  }
  const obj = parsed && typeof parsed === "object" ? (parsed.registRes && typeof parsed.registRes === "object" ? parsed.registRes : parsed) : {};
  const codes = {};
  for (const k of CODE_FIELDS) {
    if (typeof obj[k] === "number") codes[k] = obj[k];
  }
  const texts = {};
  if (withText) {
    for (const k of TEXT_FIELDS) {
      if (typeof obj[k] === "string") texts[k] = redact(obj[k], secrets);
    }
  }
  const names = Object.keys(obj).sort();
  const fields = names.slice(0, MAX_FIELDS).map((k) => k.slice(0, MAX_FIELD_NAME));
  return JSON.stringify({ bytes, fields, ...(names.length > MAX_FIELDS && { moreFields: names.length - MAX_FIELDS }), ...codes, ...texts }) + used;
}

/** Replace every raw or URL-encoded occurrence of each secret, then bound the length. Redact before cutting so a cut never exposes a partial secret. */
function redact(value, secrets) {
  let out = String(value);
  for (const s of secrets) {
    if (typeof s !== "string" || !s) continue;
    for (const v of new Set([s, encodeURIComponent(s)])) {
      out = out.replace(new RegExp(v.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "gi"), "(redacted)");
    }
  }
  return out.length > MAX_TEXT ? `${out.slice(0, MAX_TEXT)}...` : out;
}

/**
 * Build the form body for newTenantAssignmentWithDefaults.ap.
 *
 * `licenseKey` becomes `kvLicenseKey`. It is optional on the wire: when
 * omitted ASM generates a 5-user test license, which is what admin-created
 * tenants get today (UC II billing is Phase 2). Self-signup always sends it.
 */
export function buildTenantRegistrationForm(
  { tenantId, tenantName, adminEmail, contactEmail, licenseKey },
  { serviceProviderId, asmSecretKey },
  { awsAccount, awsRegion, rootDomain, natEipAddress },
) {
  // adminEmail = initial tenant admin (newTenantAdminEmail), optional. ASM
  // requires newTenantAdminEmail, so when no admin was given we send the
  // requester (contactEmail). See registerTenantWithASM for the consequence.
  const tenantAdminEmail = adminEmail || contactEmail;

  // Agreed with ASM team: display name + "-" + tenantId (amfa-443). The
  // suffix guarantees uniqueness; ASM locks the name after creation.
  const asmTenantName = `${tenantName || tenantId}-${tenantId}`;

  return new URLSearchParams({
    newTenantName: asmTenantName,
    newTenantAdminEmail: tenantAdminEmail,
    awsAccountId: awsAccount,
    asmSecretKey,
    serviceProviderId,
    awsUserPoolFqdn: `${tenantId}.apersonaid.${rootDomain}`,
    awsRegion,
    asmTenantInstallerEmail: contactEmail,
    ...(natEipAddress && { appSrvIP: natEipAddress }),
    ...(licenseKey && { kvLicenseKey: licenseKey }),
  });
}

/**
 * Decide the outcome of a newTenantAssignmentWithDefaults.ap reply from its
 * HTTP status and raw body. Only an HTTP 200 whose body carries
 * `asmClientId` and `mobileTokenKey` is success; ASM reports validation
 * failures as 203 (1.6), which `response.ok` would wrongly accept. ASM
 * also echoes its code in the JSON body (`code`, as createServiceProvider.ap
 * does), so a non-200 body code on an HTTP 200 is classified the same way.
 *
 * `secrets` (optional) are the request values whose echo must be redacted
 * before the body text is logged; see safeAsmDetail.
 *
 * Returns the ASM data object (unwrapped from `registRes` when present) or
 * throws the classified Error.
 */
export function parseAsmRegistrationResponse(status, text, secrets) {
  if (status !== 200) throw classifyAsmRegistrationError(status, text, secrets);
  let result;
  try {
    result = JSON.parse(text);
  } catch {
    throw asmError("asm_error", 200, "non-JSON body", text, secrets);
  }
  const bodyCode = Number(result?.code ?? result?.registRes?.code);
  if (Number.isInteger(bodyCode) && bodyCode !== 200) throw classifyAsmRegistrationError(bodyCode, text, secrets);
  const asmData = (result && result.registRes) || result;
  if (!asmData || !asmData.asmClientId || !asmData.mobileTokenKey) {
    throw asmError("asm_error", 200, "incomplete data", text, secrets);
  }
  return asmData;
}

function asmError(code, status, why, body, secrets) {
  const err = new Error(`ASM tenant registration failed (${status}): ${why}`);
  err.code = code;
  err.asmStatus = status;
  // Safe to log; echoed request values are redacted (see safeAsmDetail).
  err.detail = safeAsmDetail(body, { secrets });
  return err;
}

/**
 * Turn a non-200 ASM response into an Error with a stable `code` the
 * orchestrator can branch on. The message carries only the status; a
 * redacted summary of the body is on `detail` for server-side logging
 * (see safeAsmDetail) and is not returned to callers. Codes:
 *   asm_license_key_used    403 + "License Key is already used ..." (question 28):
 *                           the key is bound elsewhere; never retry with it.
 *   asm_forbidden           other 403 (bad secret, untrusted source IP, 1.6)
 *   asm_validation_failed   203 (ASM's validation code, 1.6 error catalog)
 *   asm_error               anything else
 */
export function classifyAsmRegistrationError(status, text, secrets) {
  const body = String(text || "");
  const code =
    status === 403 && KEY_USED_RE.test(body) ? "asm_license_key_used"
    : status === 403 ? "asm_forbidden"
    : status === 203 ? "asm_validation_failed"
    : "asm_error";
  return asmError(code, status, "see detail", body, secrets);
}
